-- Tenant slug: umalila
-- Run in Supabase SQL Editor. Review before executing on production.

BEGIN;

DO $$
DECLARE
  tid uuid;
BEGIN
  SELECT id INTO tid FROM public.tenants WHERE slug = 'umalila-dev' LIMIT 1;
  IF tid IS NULL THEN
    RAISE EXCEPTION 'Tenant % not found', 'umalila';
  END IF;

  -- Remove existing booking-related data for this tenant
  DELETE FROM public.order_items
  WHERE order_id IN (
    SELECT o.id FROM public.orders o
    JOIN public.bookings b ON b.id = o.booking_id
    WHERE b.tenant_id = tid
  );

  DELETE FROM public.orders
  WHERE booking_id IN (SELECT id FROM public.bookings WHERE tenant_id = tid);

  DELETE FROM public.finances
  WHERE booking_id IN (SELECT id FROM public.bookings WHERE tenant_id = tid);

  DELETE FROM public.reservation_profitability
  WHERE booking_id IN (SELECT id FROM public.bookings WHERE tenant_id = tid);

  DELETE FROM public.booking_addons
  WHERE booking_id IN (SELECT id FROM public.bookings WHERE tenant_id = tid);

  DELETE FROM public.booking_properties
  WHERE booking_id IN (SELECT id FROM public.bookings WHERE tenant_id = tid);

  CREATE TEMP TABLE _invoice_import_guest_ids ON COMMIT DROP AS
  SELECT DISTINCT guest_id FROM public.bookings WHERE tenant_id = tid AND guest_id IS NOT NULL;

  DELETE FROM public.bookings WHERE tenant_id = tid;

  DELETE FROM public.guests
  WHERE tenant_id = tid AND id IN (SELECT guest_id FROM _invoice_import_guest_ids);
END $$;

